const d = $('Prompt Verificador').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }

// El guard deterministico MANDA sobre el agente: si hay un monto no autorizado
// en el texto, se rechaza aunque el verificador haya dicho que si. Un LLM no
// puede habilitar un numero que el calculo no produjo.
let montoInventado = (d.numerosNoAutorizados || []).length > 0;
const aprobadoLLM = out.aprobado === true;
let fallaLLM = String(out.falla || '');

// ═══ CORRECCION DEL VERIFICADOR (decision de Martin 2026-07-29) ═══
//
// El verificador puede devolver el mensaje ya arreglado en vez de solo rechazar.
// Sirve para lo que se cura sacando texto: ofrecer tomar un pedido, pedir un
// archivo, explicar por que falta un dato.
//
// EL PROBLEMA QUE ESTO ABRE, Y COMO SE TAPA: el verificador pasa a ser el unico
// que escribe SIN que nadie lo audite despues (es el ultimo eslabon). Si pudiera
// tipear un monto, seria justo el agujero que v8/v9 costo cerrar.
//
// Por eso su correccion pasa por EL MISMO chequeo determinístico que el borrador
// del compositor: se extraen los numeros del texto corregido y se comparan contra
// los montos autorizados. Si mete uno que no esta, la correccion se DESCARTA entera
// (no se envia ni la corregida ni la original: se rechaza el turno). El
// verificador reescribe la prosa, nunca la plata.
const corregidoRaw = String(out.mensajeCorregido || '').trim();
let correccionAplicada = false;
let correccionRechazada = false;
let montosDeLaCorreccion = [];
let ofertasBorradas = [];

if (corregidoRaw && corregidoRaw !== String(d.borrador || '').trim()) {
  // MISMA regex que usa Prompt Verificador sobre el borrador: si divergen, el
  // guard mide una cosa distinta de la que audita.
  const enCorreccion = (corregidoRaw.match(/\$\s?[\d.]+(?:,\d+)?/g) || [])
    .map((s) => Number(s.replace(/[^\d.,]/g, '').replace(/\./g, '').replace(',', '.')))
    .filter((n) => Number.isFinite(n) && n > 0);
  const autorizados = new Set((d.montosAutorizados || []).map(Number));
  montosDeLaCorreccion = enCorreccion.filter((n) => !autorizados.has(n));

  // ═══ GUARD DE OFERTA BORRADA (Martin, 2026-07-29) ═══
  //
  // El verificador borro la promo de inmobiliarias ($15.000 llevando 6) de un
  // mensaje que la traia bien, clasificandola como "informacion innecesaria". El
  // cliente se fue con el precio del suelto y sin saber que existia un precio
  // mejor. El prompt ahora se lo prohibe explicito, pero un prompt no alcanza:
  // no fallo por no saber la regla, fallo JUZGANDO relevancia — y con la regla
  // escrita puede volver a decidir que en ese caso no aplica. El verificador es
  // el ultimo eslabon: nadie lo audita despues de esto.
  //
  // SE COMPARA EL MONTO, NO EL TEXTO. Buscar la frase literal romperia en cuanto
  // reformule, y reformular es justo lo que se le autorizo. Un monto es un
  // numero: o esta o no esta. Misma tecnica que el guard de plata de arriba.
  //
  // DEGRADACION DISTINTA a la del monto inventado: aca NO se rechaza el turno.
  // El borrador original tenia la oferta y era correcto, asi que sale ese. Tirar
  // el turno a mail seria castigar al cliente por un error del auditor.
  const montosOferta = (d.hechos || [])
    .filter((h) => h && h.ofertaBajoMinimo && Number.isFinite(Number(h.monto)))
    .map((h) => Number(h.monto));
  ofertasBorradas = montosOferta.filter((n) => !enCorreccion.includes(n));

  if (montosDeLaCorreccion.length) {
    // el verificador invento un numero al corregir: se tira la correccion Y se
    // rechaza el turno. No se cae a la original en silencio — que el auditor
    // haya tipeado plata es una senal que hay que ver en el log.
    correccionRechazada = true;
    montoInventado = true;
  } else if (ofertasBorradas.length) {
    // borro una oferta: se descarta la correccion y sale el borrador original.
    correccionRechazada = true;
  } else {
    correccionAplicada = true;
  }
}

// EL CHEQUEO DE MONTOS ES DETERMINISTICO Y MANDA EN LAS DOS DIRECCIONES.
//
// Ya mandaba para RECHAZAR (un monto no autorizado tumba un OK del LLM). Faltaba
// la direccion inversa: si el codigo comparo numero por numero y NINGUNO esta
// fuera de la lista, el LLM NO puede alegar 'precio_inventado' — no es una
// opinion, es un hecho ya verificado.
//
// Bug del 2026-07-29 (2do rechazo): el verificador rechazo $88 y $120 diciendo
// que no estaban "en la base cruda", porque el prompt le mostraba solo
// precio_lista y no la escalera de donde salen. El chequeo automatico decia OK
// y el LLM lo contradijo igual. Se arreglo el prompt (ahora ve la escalera) y
// se agrega este piso: el veredicto del codigo sobre PLATA no se discute.
let vetoInvalido = false;
if (!montoInventado && /precio_inventado/.test(fallaLLM)) {
  vetoInvalido = true;
  fallaLLM = '';  // el rechazo por plata se descarta: el codigo ya dijo que no hubo
}

// El rechazo sobrevive solo si NO era por plata (producto equivocado, no
// contesta, dato inventado son juicios legitimos del LLM sobre el texto).
const rechazoLLM = !aprobadoLLM && !vetoInvalido;
const aprobado = !montoInventado && !rechazoLLM;

const falla = montoInventado ? 'precio_inventado'
  : (aprobado ? 'ninguna' : (fallaLLM || 'otra'));

// El sobre que sale de aca es el que leen Log Turno y Log Escalacion, asi que
// tiene que traer TODAS las columnas que esos dos mapean. Si falta una, el
// INSERT escribe null; y si la columna es NOT NULL el INSERT REBOTA ENTERO y,
// con onError:continueRegularOutput, falla EN SILENCIO — cero filas y ninguna
// senal de que algo anda mal. Es exactamente el bug del 2026-07-28 (Log Turno
// escribia null en `accion`), que dejo sin datos todo el trabajo de ese dia.
const productoResuelto = (d.hechos || []).map((h) => h.producto).join(' | ')
  || (d.elegidos || []).map((c) => c.producto).join(' | ')
  || null;

// ¿SE REINTENTA? (decision de Martin 2026-07-29: un rebote al compositor y basta)
//
// Tres condiciones, y las tres tienen que darse:
//
//  1. Es la PRIMERA vuelta. `intento` viene de $runIndex del compositor, que lo
//     lleva n8n — no de un contador nuestro que se pueda desincronizar.
//
//  2. NO fue por plata. `montoInventado` significa que el codigo encontro un
//     numero que el calculo no produjo. Reescribir la prosa no arregla eso: los
//     montos autorizados son IDENTICOS en la segunda vuelta (Calcular Montos no
//     se re-ejecuta), asi que el reintento solo gastaria dos llamadas mas para
//     llegar al mismo rechazo. Va derecho a mail.
//
//  3. Hay algo concreto que corregir. Si el auditor rechazo sin decir por que,
//     el compositor no tiene con que trabajar y el reintento es una moneda al
//     aire con la plata del cliente en el medio.
const intento = Number(d.intento) || 1;
const hayFeedback = String(out.motivo || '').trim().length > 0
  || String(out.queFalta || '').trim().length > 0;

// ═══ RE-AUDITORIA: la plata la metio EL AUDITOR, no el compositor ═══
// (Martin, 2026-07-31)
//
// Caso real que motivo esto (lona UV 3x2): el compositor escribio un mensaje
// CORRECTO, con montos autorizados. El verificador lo aprobo — y de paso
// "corrigio" multiplicando 22.000 x 6 y tipeando $132.000, que el calculo no
// habia producido. El guard tumbo el turno entero y el cliente se fue a mail
// teniendo una respuesta valida escrita y aprobada.
//
// Mandar eso al COMPOSITOR no tiene sentido: su borrador estaba bien, no hay
// nada que reescribir. El que se equivoco fue el auditor, asi que vuelve AL
// AUDITOR con el numero que invento, para que rehaga la correccion sin el o
// directamente apruebe el original.
//
// Se distingue por `correccionRechazada`: si esta en true, la plata salio de
// `mensajeCorregido` (del auditor). Si esta en false y montoInventado es true,
// la plata estaba en el borrador del compositor — eso NO es re-auditable, es
// el caso viejo y va a mail.
//
// `$runIndex` del verificador lleva la cuenta: 0 la primera auditoria, 1 la
// segunda. Mismo mecanismo que el reintento del compositor, y por la misma
// razon — un contador propio en el sobre se desincroniza.
let auditoria = 1;
try { auditoria = Number($runIndex) + 1; } catch (e) { auditoria = 1; }
if (!Number.isFinite(auditoria) || auditoria < 1) auditoria = 1;

const plataDelAuditor = montosDeLaCorreccion.length > 0;
const puedeReauditar = !aprobado && plataDelAuditor && auditoria < 2;

// El reintento al COMPOSITOR sigue igual, pero no se dispara si ya se decidio
// re-auditar: son dos caminos distintos para dos culpables distintos.
const puedeReintentar = !aprobado && !puedeReauditar
  && intento < 2 && !montoInventado && hayFeedback;

// por que NO se reintenta, para poder auditarlo desde bot.decisiones
const motivoNoReintento = (aprobado || puedeReintentar || puedeReauditar) ? null
  : (auditoria >= 2 && plataDelAuditor ? 'auditor_reincidio'
    : intento >= 2 ? 'ya_reintento'
    : montoInventado ? 'plata_no_es_reintentable'
    : 'sin_feedback_accionable');

return [{ json: {
  ...d,
  aprobado,
  aprobadoLLM,
  montoInventado,
  // el LLM quiso rechazar por plata cuando el codigo ya habia dicho que no
  // habia monto inventado. Se registra para vigilar si pasa seguido: seria
  // sintoma de que el prompt del verificador sigue mostrando mal la evidencia.
  vetoInvalido,
  falla,
  intento,
  puedeReintentar,
  // re-auditoria: el auditor tipeo plata y vuelve a su propia correccion
  auditoria,
  puedeReauditar,
  montosDeLaCorreccion,
  motivoNoReintento,
  motivoVerificador: String(out.motivo || ''),
  // Log Escalacion mapea `.motivo`: se emite con ese nombre tambien.
  motivo: String(out.motivo || '') || ('v10 falla=' + falla),
  queFalta: String(out.queFalta || ''),
  // lo que sale al cliente: la correccion del verificador si la hubo y paso el
  // guard de plata, si no el borrador del compositor.
  final: aprobado ? (correccionAplicada ? corregidoRaw : d.borrador) : '',
  correccionAplicada,
  correccionRechazada,
  mensajeCorregido: correccionAplicada ? corregidoRaw : '',
  queCorregi: String(out.queCorregi || ''),
  accion: aprobado ? 'respuesta_verificada' : 'handoff',
  notas: 'v10-agents falla=' + falla + ' idxInv=' + (d.idxInvalidos || 0)
    + ' intento=' + intento
    + (auditoria > 1 ? ' auditoria=' + auditoria : '')
    + (puedeReintentar ? ' REINTENTA' : '')
    + (puedeReauditar ? ' RE-AUDITA' : '')
    + (auditoria > 1 && aprobado ? ' RESCATADO-POR-RE-AUDITORIA' : '')
    + (motivoNoReintento ? ' no-reintenta=' + motivoNoReintento : '')
    + (intento > 1 && aprobado ? ' RESCATADO-POR-REINTENTO' : '')
    + (correccionAplicada ? ' CORREGIDO-POR-VERIFICADOR(' + String(out.queCorregi || '?').slice(0, 120) + ')' : '')
    + (montosDeLaCorreccion.length ? ' CORRECCION-CON-PLATA-INVENTADA(' + montosDeLaCorreccion.join(',') + ')' : '')
    + (ofertasBorradas.length ? ' CORRECCION-BORRO-OFERTA(' + ofertasBorradas.join(',') + ')' : '')
    + (d.feedbackPrevio ? ' feedback1=' + String(d.feedbackPrevio).slice(0, 160) : '')
    + (vetoInvalido ? ' VETO-INVALIDO(el LLM alego precio_inventado con chequeo OK)' : ''),
  // columnas que Log Turno espera y que la cadena de agentes no producia
  productoResuelto,
  filasSql: Number(d.nFilas) || 0,
  senales: {
    intencion: d.intencion || null,
    confianzaIntencion: d.confianzaIntencion || 0,
    nCandidatos: (d.candidatos || []).length,
    nElegidos: (d.elegidos || []).length,
    nHechos: (d.hechos || []).length,
    idxInvalidos: d.idxInvalidos || 0,
    dudaNicho: !!d.dudaNicho,
    montoInventado,
    aprobadoLLM,
    vetoInvalido,
    falla,
    intento,
    puedeReintentar,
    motivoNoReintento,
    // el reintento salvo un turno que antes moria en mail
    rescatadoPorReintento: intento > 1 && aprobado,
    // que vuelta de AUDITORIA es (el auditor puede rehacer su correccion una vez)
    auditoria,
    puedeReauditar,
    // la re-auditoria salvo un turno que el propio auditor habia tumbado
    rescatadoPorReauditoria: auditoria > 1 && aprobado,
    // el verificador edito el mensaje en vez de rechazarlo
    correccionAplicada,
    // el verificador tipeo un monto que el calculo no produjo: vigilar
    correccionRechazada,
    // el verificador borro una oferta por cantidad al corregir. Si aparece
    // seguido, el parrafo del prompt no esta alcanzando.
    ofertasBorradas: ofertasBorradas.length,
  },
} }];
